{
  "findings": [
    {
      "check_id": "CKV_AWS_126",
      "title": "Launch Configuration does not have IMDSv2 enforced",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not specify metadata_options, meaning it defaults to allowing both IMDSv1 and IMDSv2. IMDSv1 is vulnerable to Server-Side Request Forgery (SSRF) attacks which can expose instance credentials."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"levelup-launchconfig\" {\n  name_prefix     = \"levelup-launchconfig\"\n  image_id        = lookup(var.AMIS, var.AWS_REGION)\n  instance_type   = \"t2.micro\"\n  key_name        = aws_key_pair.levelup_key.key_name\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n}",
  "fix_summary": "Added a metadata_options block to the aws_launch_configuration resource with http_tokens set to 'required' to enforce IMDSv2 and mitigate SSRF risks."
}
